import { toCamelCase } from '../../common/string.js';

/**
 * HTTP Status Codes enum.
 * Based on MDN Web Docs and IANA HTTP Status Code Registry.
 * Covers all registered status codes from RFC 9110 and related RFCs.
 *
 * (Generated by Junie)
 */
export enum HttpStatus {
  // Informational responses (100–199)
  CONTINUE = 100,
  SWITCHING_PROTOCOLS = 101,
  PROCESSING = 102,
  EARLY_HINTS = 103,

  // Successful responses (200–299)
  OK = 200,
  CREATED = 201,
  ACCEPTED = 202,
  NON_AUTHORITATIVE_INFORMATION = 203,
  NO_CONTENT = 204,
  RESET_CONTENT = 205,
  PARTIAL_CONTENT = 206,
  MULTI_STATUS = 207,
  ALREADY_REPORTED = 208,
  IM_USED = 226,

  // Redirection messages (300–399)
  MULTIPLE_CHOICES = 300,
  MOVED_PERMANENTLY = 301,
  FOUND = 302,
  SEE_OTHER = 303,
  NOT_MODIFIED = 304,
  USE_PROXY = 305,
  TEMPORARY_REDIRECT = 307,
  PERMANENT_REDIRECT = 308,

  // Client error responses (400–499)
  BAD_REQUEST = 400,
  UNAUTHORIZED = 401,
  PAYMENT_REQUIRED = 402,
  FORBIDDEN = 403,
  NOT_FOUND = 404,
  METHOD_NOT_ALLOWED = 405,
  NOT_ACCEPTABLE = 406,
  PROXY_AUTHENTICATION_REQUIRED = 407,
  REQUEST_TIMEOUT = 408,
  CONFLICT = 409,
  GONE = 410,
  LENGTH_REQUIRED = 411,
  PRECONDITION_FAILED = 412,
  CONTENT_TOO_LARGE = 413,
  URI_TOO_LONG = 414,
  UNSUPPORTED_MEDIA_TYPE = 415,
  RANGE_NOT_SATISFIABLE = 416,
  EXPECTATION_FAILED = 417,
  IM_A_TEAPOT = 418,
  MISDIRECTED_REQUEST = 421,
  UNPROCESSABLE_CONTENT = 422,
  LOCKED = 423,
  FAILED_DEPENDENCY = 424,
  TOO_EARLY = 425,
  UPGRADE_REQUIRED = 426,
  PRECONDITION_REQUIRED = 428,
  TOO_MANY_REQUESTS = 429,
  REQUEST_HEADER_FIELDS_TOO_LARGE = 431,
  UNAVAILABLE_FOR_LEGAL_REASONS = 451,

  // Server error responses (500–599)
  INTERNAL_SERVER_ERROR = 500,
  NOT_IMPLEMENTED = 501,
  BAD_GATEWAY = 502,
  SERVICE_UNAVAILABLE = 503,
  GATEWAY_TIMEOUT = 504,
  HTTP_VERSION_NOT_SUPPORTED = 505,
  VARIANT_ALSO_NEGOTIATES = 506,
  INSUFFICIENT_STORAGE = 507,
  LOOP_DETECTED = 508,
  NOT_EXTENDED = 510,
  NETWORK_AUTHENTICATION_REQUIRED = 511,
}

/**
 * Derived type containing only error status codes (>= 400).
 * Includes client errors (4xx) and server errors (5xx).
 *
 * (Generated by Junie)
 */
export type HttpErrorStatus =
  | HttpStatus.BAD_REQUEST
  | HttpStatus.UNAUTHORIZED
  | HttpStatus.PAYMENT_REQUIRED
  | HttpStatus.FORBIDDEN
  | HttpStatus.NOT_FOUND
  | HttpStatus.METHOD_NOT_ALLOWED
  | HttpStatus.NOT_ACCEPTABLE
  | HttpStatus.PROXY_AUTHENTICATION_REQUIRED
  | HttpStatus.REQUEST_TIMEOUT
  | HttpStatus.CONFLICT
  | HttpStatus.GONE
  | HttpStatus.LENGTH_REQUIRED
  | HttpStatus.PRECONDITION_FAILED
  | HttpStatus.CONTENT_TOO_LARGE
  | HttpStatus.URI_TOO_LONG
  | HttpStatus.UNSUPPORTED_MEDIA_TYPE
  | HttpStatus.RANGE_NOT_SATISFIABLE
  | HttpStatus.EXPECTATION_FAILED
  | HttpStatus.IM_A_TEAPOT
  | HttpStatus.MISDIRECTED_REQUEST
  | HttpStatus.UNPROCESSABLE_CONTENT
  | HttpStatus.LOCKED
  | HttpStatus.FAILED_DEPENDENCY
  | HttpStatus.TOO_EARLY
  | HttpStatus.UPGRADE_REQUIRED
  | HttpStatus.PRECONDITION_REQUIRED
  | HttpStatus.TOO_MANY_REQUESTS
  | HttpStatus.REQUEST_HEADER_FIELDS_TOO_LARGE
  | HttpStatus.UNAVAILABLE_FOR_LEGAL_REASONS
  | HttpStatus.INTERNAL_SERVER_ERROR
  | HttpStatus.NOT_IMPLEMENTED
  | HttpStatus.BAD_GATEWAY
  | HttpStatus.SERVICE_UNAVAILABLE
  | HttpStatus.GATEWAY_TIMEOUT
  | HttpStatus.HTTP_VERSION_NOT_SUPPORTED
  | HttpStatus.VARIANT_ALSO_NEGOTIATES
  | HttpStatus.INSUFFICIENT_STORAGE
  | HttpStatus.LOOP_DETECTED
  | HttpStatus.NOT_EXTENDED
  | HttpStatus.NETWORK_AUTHENTICATION_REQUIRED;

/**
 * Deduce status text from the code.
 * @param statusCode
 */
export const httpStatusText = (statusCode: HttpStatus): string => {
  if (!HttpStatus[statusCode]) {
    throw new Error(`Unknown http status code: ${statusCode}`);
  }

  if (statusCode === HttpStatus.OK) {
    return HttpStatus[HttpStatus.OK];
  }

  return HttpStatus[statusCode]
    .split('_')
    .map(toCamelCase)
    .join(' ');
};
